      "name": "Nat.iSup_lt_succ'",
      "module_name": "Mathlib.Data.Nat.Lattice",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : CompleteLattice α] (u : ℕ → α) (n : ℕ),\n  ⨆ k, ⨆ (_ : k < n + 1), u k = u 0 ⊔ ⨆ k, ⨆ (_ : k < n), u (k + 1)"
    },
    {
      "name": "Polynomial.ctorIdx",
