      "kind": "definition",
      "type": "{α : Type u_2} → [DecidableEq α] → [AddMonoid α] → Finset α →o ℕ"
    },
    {
      "name": "MeasureTheory.Measure.LebesgueDecomposition.iSup_succ_eq_sup",
      "module_name": "Mathlib.MeasureTheory.Measure.Decomposition.Lebesgue",
      "kind": "theorem",
      "type": "∀ {α : Sort u_2} (f : ℕ → α → ENNReal) (m : ℕ) (a : α),\n  ⨆ k, ⨆ (_ : k ≤ m + 1), f k a = max (f m.succ a) (⨆ k, ⨆ (_ : k ≤ m), f k a)"
    },
    {
      "name": "PolynomialLaw.ctorIdx",
