      "kind": "definition",
      "type": "{R : Type u} →\n  {inst : CommSemiring R} →\n    {M : Type u_1} →\n      {inst_1 : AddCommMonoid M} →\n        {inst_2 : Module R M} → {N : Type u_2} → {inst_3 : AddCommMonoid N} → {inst_4 : Module R N} → (M →ₚₗ[R] N) → ℕ"
    },
    {
      "name": "Polynomial.supDegree_eq_natDegree",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Support",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p : Polynomial R), AddMonoidAlgebra.supDegree id p.toFinsupp = p.natDegree"
    },
    {
      "name": "MvPolynomial.supDegree_esymm",
      "module_name": "Mathlib.RingTheory.MvPolynomial.Symmetric.FundamentalTheorem",
      "kind": "theorem",
      "type": "∀ {R : Type u_3} {n m : ℕ} [inst : CommSemiring R] {i : Fin n} [Nontrivial R],\n  ↑i < m →\n    ⇑(ofLex (AddMonoidAlgebra.supDegree (⇑toLex) (MvPolynomial.esymm (Fin m) R (↑i + 1)))) =\n      (Fin.accumulate n m) ⇑fun₀ | i => 1"
    }
  ]
